SELECT ?point ?tsId ?class WHERE {
  ?zone a brick:Zone ;
        brick:hasIdentifier "Perimeter_top_ZN_1" .
  ?point a brick:ElectricPowerSensor ;
         brick:hasProperty brick:ElectricLightingPower ;
         brick:pointLocation ?zone .
  ?point ref:hasExternalReference ref:hasTimeseriesId .
  ?point ref:hasTimeseriesId ?tsId .
  ?point ?class .
}

SELECT ?point ?tsId WHERE {
  ?zone a brick:Zone ;
        brick:hasIdentifier "Perimeter_top_ZN_1" .
  ?point a brick:OccupancySensor ;
         brick:pointLocation ?zone .
  ?point ref:hasTimeseriesId ?tsId .
}

SELECT ?p ?o WHERE {
  ?zone a brick:Zone .
  ?zone rdf:type ?o .
  ?zone brick:hasIdentifier ?p .
} LIMIT 30

